package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Takes the person's statement: records their due-total now, binds each of their claims that counts to the
 * figure it has now (a live one raised to the sheet's floor), and unbinds (live again) each that does not. The due-total is their counting claims'
 * dues added up (each figure plus any late charge on it — the charge is never bound, it keeps following the
 * sheet's today); n/a when their grade on the sheet's today has no rate there and no counting claim has a figure (kept, or at the
 * rate for the grade in force on its date).
 */
public class TakeStatement {
    public void take(@Val Person person, ClaimRepository claims, PersonRepository people, RateRepository rates,
            SheetRepository sheets, SettingRepository settings, Out<Statement> statement, Out<Person> updated) {
        LocalDate today = sheets.today(person.sheetId());
        List<Rate> sheetRates = rates.findAll(person.sheetId());
        BigDecimal floor = settings.floor(person.sheetId());
        LateCharge late = settings.lateCharge(person.sheetId(), today);
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        boolean kept = false;
        int counted = 0;
        List<Claim> personClaims = claims.findForPerson(person.sheetId(), person.id());
        Rounding rounding = settings.rounding(person.sheetId(), today, personClaims);
        for (Claim claim : personClaims) {
            if (!person.counts(claim)) {
                claims.bindStatement(claim, false, null);
                continue;
            }
            boolean fixed = claim.due() != null || (claim.stated() && claim.statedDue() != null);
            BigDecimal figure = claim.figure(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()), floor, rounding);
            claims.bindStatement(claim, true, figure);
            counted++;
            kept |= fixed || figure != null;
            if (figure != null) {
                total = total.add(figure).add(late.on(claim, figure, rounding.modeFor(claim)));
            }
        }
        String dueTotal = Rate.inForce(sheetRates, person.grade(), today) == null && !kept ? "n/a"
                : total.setScale(2).toPlainString();
        statement.set(new Statement(person.name(), dueTotal, counted));
        updated.set(people.recordStatement(person, dueTotal, today));
    }
}
package net.officefloor.hq.app.rollup;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.LateCharge;
import net.officefloor.hq.app.claim.Rounding;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.stereotype.Service;

/**
 * Works out a sheet's figures as the screen shows them: a person's claimed is their counting claims' amounts
 * added up; their due-total those claims' dues (live figures raised to the sheet's floor and rounded by its policy date, plus
 * any late charge on the overdue ones) added up, n/a when their grade on the sheet's today has no
 * rate there and no counting claim has a figure (kept, or at the rate for the grade in force on its date). The sheet's totals add these up, skipping n/a.
 */
@Service
public class RollupService {

    private static final String NA = "n/a";

    private final PersonRepository people;
    private final ClaimRepository claims;
    private final RateRepository rates;
    private final SheetRepository sheets;
    private final SettingRepository settings;

    public RollupService(PersonRepository people, ClaimRepository claims, RateRepository rates,
            SheetRepository sheets, SettingRepository settings) {
        this.people = people;
        this.claims = claims;
        this.rates = rates;
        this.sheets = sheets;
        this.settings = settings;
    }

    /** The sheet's figures as the store holds them now. */
    public Rollup compute(String sheetId) {
        LocalDate today = sheets.today(sheetId);
        List<Rate> sheetRates = rates.findAll(sheetId);
        BigDecimal floor = settings.floor(sheetId);
        LateCharge late = settings.lateCharge(sheetId, today);
        List<Claim> sheetClaims = claims.findAll(sheetId);
        Rounding rounding = settings.rounding(sheetId, today, sheetClaims);
        Map<Long, Rollup.Figures> figures = new LinkedHashMap<>();
        BigDecimal claimedTotal = BigDecimal.ZERO.setScale(2);
        BigDecimal dueTotal = BigDecimal.ZERO.setScale(2);
        for (Person person : people.findAll(sheetId)) {
            BigDecimal claimed = BigDecimal.ZERO.setScale(2);
            BigDecimal due = BigDecimal.ZERO.setScale(2);
            boolean kept = false;
            for (Claim claim : sheetClaims) {
                if (claim.personId() != person.id() || !person.counts(claim)) {
                    continue;
                }
                claimed = claimed.add(claim.amount());
                kept |= claim.due() != null || (claim.stated() && claim.statedDue() != null);
                BigDecimal figure = claim.due(Rate.inForce(sheetRates, person.gradeOn(claim.date()), claim.date()), floor, late, rounding);
                if (figure != null) {
                    kept = true;
                    due = due.add(figure);
                }
            }
            boolean na = Rate.inForce(sheetRates, person.grade(), today) == null && !kept;
            claimedTotal = claimedTotal.add(claimed);
            if (!na) {
                dueTotal = dueTotal.add(due);
            }
            figures.put(person.id(), new Rollup.Figures(person.name(), show(claimed), na ? NA : show(due)));
        }
        return new Rollup(figures, show(claimedTotal), show(dueTotal));
    }

    private static String show(BigDecimal value) {
        return value.setScale(2).toPlainString();
    }
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { counts } from '../claims/claims';
import type { Claim } from '../claims/claims';
import { latePeriods } from '../overdue/dueBy';
import { gradeOn } from '../people/people';
import type { GradeFrom } from '../people/people';
import { sheetKey, useCurrentSheet } from '../session/session';
import type { DueRules } from '../settings/settings';

/**
 * A grade's rate as the store holds it: a percent with two decimals, in force from its from-date
 * (yyyy-MM-dd; null: from the beginning of time) until the grade's next rate takes over.
 */
export type Rate = { grade: string; rate: string; from: string | null };

/** The fields the rate form submits; a blank from-date is from the beginning of time. */
export type RateInput = { grade: string; rate: string; from: string };

/** What a due shows when its grade has no rate. */
export const NA = 'n/a';

/** 0.00 or more, with at most two decimals. */
export const PERCENT = /^(\d{1,5}(\.\d{1,2})?|\.\d{1,2})$/;

/** The query key for the sheet's rates; under sheetKey, so re-loading the sheet re-reads them. */
export const ratesKey = (sheet: string) => [...sheetKey(sheet), 'rates'] as const;

/** The sheet's rates, by grade and then from-date (from the start first). */
export function useRates() {
  const [sheet] = useCurrentSheet();
  return useQuery({
    queryKey: ratesKey(sheet),
    queryFn: () => getJson<Rate[]>(`/api/sheets/${encodeURIComponent(sheet)}/rates`),
    enabled: !!sheet,
  });
}

/**
 * The grade's rate (two decimals) in force on the date: the one with the latest from-date on or
 * before it, a rate with no from-date applying from the start; undefined when none applies.
 */
export function rateFor(rates: Rate[], grade: string | undefined, date: string): string | undefined {
  let found: Rate | undefined;
  for (const r of rates) {
    if (r.grade !== grade || (r.from !== null && r.from > date)) continue;
    if (!found || (found.from ?? '') < (r.from ?? '')) found = r;
  }
  return found?.rate;
}

/** A two-decimal value as whole hundredths, exactly. */
const hundredths = (value: string) => Math.round(Number(value) * 100);

/** How a half is rounded: half up (away from zero) or half to even. */
export type Rounding = 'half-up' | 'half-even';

/**
 * How a claim's live figures round: half up when it is dated before the sheet's policy date, half to
 * even on or after it. A correction rounds by the date of the claim it corrects, not its own.
 */
export function roundingFor(claim: Claim, rules: DueRules): Rounding {
  const date = claim.corrects !== null ? (rules.claimDates.get(claim.corrects) ?? claim.date) : claim.date;
  return date < rules.policyDate ? 'half-up' : 'half-even';
}

/**
 * An amount times a percent rate, divided by 100, rounded to two decimals (half to even unless told
 * otherwise); n/a with no rate. Worked in whole hundredths so it is exact: cents × basis points / 10000.
 */
export function due(amount: string, rate: string | undefined, rounding: Rounding = 'half-even'): string {
  if (rate === undefined) return NA;
  return percentOf(hundredths(amount), hundredths(rate), rounding);
}

/** Cents times basis points / 10000, rounded to two decimals as told. */
function percentOf(amountCents: number, basisPoints: number, rounding: Rounding): string {
  const product = amountCents * basisPoints;
  const whole = Math.floor(Math.abs(product) / 10000);
  const rest = Math.abs(product) - whole * 10000;
  const up = rest > 5000 || (rest === 5000 && (rounding === 'half-up' || whole % 2 === 1));
  const cents = Math.sign(product) * (whole + (up ? 1 : 0));
  return (cents / 100).toFixed(2);
}

/** A live due raised to the floor (both two decimals); n/a stays n/a. */
export function floored(value: string, floor: string): string {
  return value !== NA && hundredths(value) < hundredths(floor) ? Number(floor).toFixed(2) : value;
}

/**
 * A claim's figure: the figure its statement bound it to, else its amount at the rate in force on its
 * date for the person's grade in force on that date, rounded by the policy date, at least the sheet's floor —
 * a correction has no floor.
 */
function claimFigure(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (claim.stated) return claim.statedDue ?? NA;
  const live = due(claim.amount, rateFor(rates, gradeOn(grades, claim.date), claim.date), roundingFor(claim, rules));
  return claim.corrects !== null ? live : floored(live, rules.floor);
}

/**
 * The late charge on a figure: the late percent of it for every full 30 days the claim is overdue,
 * rounded like the claim's due; 0.00 when it is not overdue, and always for a correction.
 */
export function lateCharge(claim: Claim, figure: string, rules: DueRules): string {
  if (claim.corrects !== null) return '0.00';
  const periods = latePeriods(claim, rules.terms, rules.today);
  return percentOf(hundredths(figure), hundredths(rules.latePct) * periods, roundingFor(claim, rules));
}

/**
 * A claim's due: the one fixed when it was settled (any late charge frozen in), else its figure plus
 * the late charge on it while it is overdue. The charge is never bound by a statement: it follows the
 * sheet's today.
 */
export function claimDue(claim: Claim, rates: Rate[], grades: GradeFrom[], rules: DueRules): string {
  if (claim.due !== null) return claim.due;
  const figure = claimFigure(claim, rates, grades, rules);
  return figure === NA ? NA : total([figure, lateCharge(claim, figure, rules)]);
}

/** Whether a claim keeps a figure whatever the rates: fixed when settled, or bound by a statement. */
const keepsFigure = (c: Claim) => c.due !== null || (c.stated && c.statedDue !== null);

/**
 * A person's due-total: the figures of their claims that count, added up (0.00 with none). With no
 * rate in force on the sheet's today for their grade on that day it is n/a, unless a claim has a figure (kept
 * when settled or stated, or at the rate for the grade in force on its date): then it is the figures there are,
 * added up. While they are held, their open claims do not count.
 */
export function personDue(
  claims: Claim[],
  rates: Rate[],
  grades: GradeFrom[],
  held: boolean,
  rules: DueRules,
): string {
  const counted = claims.filter((c) => counts(c, held));
  const figures = counted.map((c) => claimDue(c, rates, grades, rules));
  const anyFigure = counted.some(keepsFigure) || figures.some((f) => f !== NA);
  if (rateFor(rates, gradeOn(grades, rules.today), rules.today) === undefined && !anyFigure) {
    return NA;
  }
  return total(figures);
}

/** Dues added up, skipping n/a; with two decimals, added in cents so it is exact. */
export function total(dues: string[]): string {
  const cents = dues.filter((d) => d !== NA).reduce((sum, d) => sum + hundredths(d), 0);
  return (cents / 100).toFixed(2);
}
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { sheetKey, useCurrentSheet } from '../session/session';

/** Where a claim is in its life: DRAFT -> OPEN -> SETTLED; DRAFT or OPEN -> VOID. */
